<script setup lang="ts">const props = defineProps<{ clues: string[]; revealedIndexes: number[] }>(); const emit = defineEmits<{ reveal: [index: number] }>()</script>
<template><ol class="clue-list"><li v-for="(clue, index) in props.clues" :key="index" :class="{ revealed: props.revealedIndexes.includes(index), clickable: !props.revealedIndexes.includes(index) }" @click="emit('reveal', index)"><span class="clue-number">{{ String(index + 1).padStart(2, '0') }}</span><span class="clue-text">{{ props.revealedIndexes.includes(index) ? clue : 'Clique para revelar esta dica' }}</span><img v-if="props.revealedIndexes.includes(index)" class="clue-check" src="/design/icons/check.svg" alt="Revelada" /><span v-else class="clue-arrow" aria-hidden="true">›</span></li></ol></template>
